diff --git a/packages/workflow/src/expressions/native-evaluation/evaluator.ts b/packages/workflow/src/expressions/native-evaluation/evaluator.ts
index 298451317..7771d7761 100644
--- a/packages/workflow/src/expressions/native-evaluation/evaluator.ts
+++ b/packages/workflow/src/expressions/native-evaluation/evaluator.ts
@@ -175,15 +175,21 @@ function assertPreflightSize(receiver: unknown, method: string, args: unknown[])
 	} else if (method === 'flat' && isArray(receiver)) {
 		const depth = args.length === 0 ? 1 : toNum(args[0]);
 		upperBound = flatSize(receiver, depth);
-	} else if (method === 'replaceAll' && typeof receiver === 'string') {
+	} else if ((method === 'replace' || method === 'replaceAll') && typeof receiver === 'string') {
 		// A missing replacement inserts the string "undefined".
 		const replacement = args.length < 2 ? 'undefined' : toStr(args[1]);

-		// `$&`, `$\``, `$'` splice match context into every replacement, so
-		// the result is not bounded by the replacement's length.
+		// `$&`, `$\``, `$'` splice match context into the replacement, so the
+		// result is not bounded by the replacement's length (a single
+		// replace() with many `$'` still multiplies the receiver).
 		if (replacement.includes('$')) throw new EngineFallbackError();

-		upperBound = (receiver.length + 1) * (replacement.length + 1);
+		// Arguments are primitives, so the pattern is a string: replace()
+		// substitutes at most one match, replaceAll() at most one per gap.
+		upperBound =
+			method === 'replace'
+				? receiver.length + replacement.length
+				: (receiver.length + 1) * (replacement.length + 1);
 	} else if (method === 'join' && isArray(receiver)) {
 		// Only an undefined separator means ","; null joins with "null".
 		const separator = args[0] === undefined ? ',' : toStr(args[0]);
diff --git a/packages/workflow/test/native-evaluation-corpus.ts b/packages/workflow/test/native-evaluation-corpus.ts
index 6ff2dacfd..9bb537504 100644
--- a/packages/workflow/test/native-evaluation-corpus.ts
+++ b/packages/workflow/test/native-evaluation-corpus.ts
@@ -152,6 +152,7 @@ export const HANDLED_CORPUS: string[] = [
 	// a missing replacement inserts "undefined", a null separator joins with
 	// "null".
 	"={{ $json.item.big.replaceAll('y') }}",
+	"={{ $json.item.bigger.replace('', $json.item.filler) }}",
 	'={{ $json.item.manyEmpty.join(null) }}',
 ];

@@ -173,6 +174,10 @@ export const RUNTIME_BAILOUT_CORPUS: string[] = [
 	"={{ $json.item.big.replaceAll('', $json.item.filler) }}",
 	// `$\`` splices the text before each match into the result.
 	"={{ $json.item.name.replaceAll('o', '$`') }}",
+	// replace() splices match context the same way: many `$'` in one
+	// replacement multiply the receiver.
+	"={{ $json.item.name.replace('o', '$`') }}",
+	"={{ $json.item.bigger.replace('', \"$'$'$'$'$'$'$'\") }}",
 	// A receiver above MAX_RESULT_LENGTH is the engine's work, whatever the
 	// method. (concat is bounded the same way, by receiver plus arguments; a
 	// corpus entry would make quickjs marshal a million-element result.)
